package studio.solocamera;
import android.content.Context;import android.net.Uri;import androidx.media3.common.*;import androidx.media3.transformer.*;import java.io.*;import java.nio.*;import java.util.*;
/** Original synthesized accents follow their title object, never an unrelated audio row. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class EditorTitleSounds {
 static final long DURATION=950;private static File directory;
 static void init(Context c){directory=new File(c.getApplicationContext().getCacheDir(),"creator-title-sounds");directory.mkdirs();}
 static boolean active(EditorProject.Clip c){return EditorProfessionTitles.profession(c.titleDesign-1)&&c.titleSound&&c.titleSoundVolume>0&&c.titleMotion>0;}
 static synchronized File file(EditorProject.Clip c)throws IOException{if(directory==null)throw new IOException("Title sound cache unavailable");int id=c.titleDesign-1;File target=new File(directory,"profession-v1-"+id+".wav");if(target.isFile()&&target.length()==45644)return target;int rate=24000,n=22800;ByteBuffer wav=ByteBuffer.allocate(44+n*2).order(ByteOrder.LITTLE_ENDIAN);wav.put(new byte[]{82,73,70,70}).putInt(36+n*2).put(new byte[]{87,65,86,69,102,109,116,32}).putInt(16).putShort((short)1).putShort((short)1).putInt(rate).putInt(rate*2).putShort((short)2).putShort((short)16).put(new byte[]{100,97,116,97}).putInt(n*2);Random random=new Random(701+id);double low=0,freq=330*Math.pow(2,((id-88)%10)/12.0);for(int i=0;i<n;i++){double t=i/(double)rate,noise=random.nextDouble()*2-1;low=.72*low+.28*noise;double whoosh=Math.sin(Math.PI*Math.min(1,t/.38))*Math.exp(-t*4)*(noise-low)*.20,hit=0;for(int j=0;j<3;j++){double u=t-.25-j*.075;if(u>=0){double f=freq*Math.pow(2,(j==0?0:j==1?4:7)/12.0);hit+=Math.sin(u*2*Math.PI*f)*Math.min(1,u/.008)*Math.exp(-u*9)*.15;}}double end=Math.min(1,(.95-t)/.12);wav.putShort((short)(Math.max(-.85,Math.min(.85,(whoosh+hit)*end))*32767));}File tmp=new File(directory,target.getName()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(wav.array());}if(!tmp.renameTo(target))throw new IOException("Could not save title sound");return target;}
 static List<EditedMediaItemSequence> sequences(EditorProject project){ArrayList<EditedMediaItemSequence> result=new ArrayList<>();for(EditorProject.Caption caption:project.captions){EditorProject.Clip c=caption.style;if(!active(c)||caption.at>=project.duration())continue;try{long length=Math.min(DURATION,caption.end-caption.at);MediaItem source=new MediaItem.Builder().setUri(Uri.fromFile(file(c))).setClippingConfiguration(new MediaItem.ClippingConfiguration.Builder().setEndPositionMs(length).build()).build();EditedMediaItemSequence.Builder sequence=new EditedMediaItemSequence.Builder().experimentalSetForceAudioTrack(true);if(caption.at>0)sequence.addGap(caption.at*1000);sequence.addItem(new EditedMediaItem.Builder(source).setDurationUs(DURATION*1000).setRemoveVideo(true).setEffects(new Effects(Collections.singletonList(new GainAudioProcessor((float)c.titleSoundVolume)),Collections.emptyList())).build());result.add(sequence.build());}catch(IOException e){throw new IllegalStateException("Could not prepare preset sound",e);}}return result;}
}
